mapper.update:
UPDATE media_asset_application
status = #{update.status}, decision_remark = #{update.remark}, decided_at = NOW(), current_node_index = #{update.nodeIndex}, approver_id = #{update.approverId}, approver_name = #{update.approverName}, nodes_snapshot = #{update.nodes}, updated_by = #{update.operatorId}
WHERE id = #{update.id} AND status = #{update.expectedStatus} AND deleted_at = 0

mapper.sql:
(
    a.status = 'PENDING'
    AND (
        (
            COALESCE(
                JSON_UNQUOTE(
                    JSON_EXTRACT(
                        a.nodes_snapshot,
                        CONCAT('$[', a.current_node_index, '].approverType')
                    )
                ),
                'USERS'
            ) = 'USERS'
            AND (
                a.approver_id = #{query.userId}
                OR EXISTS (
                    SELECT 1
                    FROM JSON_TABLE(
                        COALESCE(
                            JSON_EXTRACT(
                                a.nodes_snapshot,
                                CONCAT('$[', a.current_node_index, '].approverIds')
                            ),
                            JSON_ARRAY()
                        ),
                        '$[*]' COLUMNS (principal_id VARCHAR(32) PATH '$')
                    ) direct_principal
                    WHERE direct_principal.principal_id = CAST(#{query.userId} AS CHAR)
                )
            )
        )
        OR (
            JSON_UNQUOTE(
                JSON_EXTRACT(
                    a.nodes_snapshot,
                    CONCAT('$[', a.current_node_index, '].approverType')
                )
            ) = 'ROLES'
            AND EXISTS (
                SELECT 1
                FROM JSON_TABLE(
                    COALESCE(
                        JSON_EXTRACT(
                            a.nodes_snapshot,
                            CONCAT('$[', a.current_node_index, '].roleIds')
                        ),
                        JSON_ARRAY()
                    ),
                    '$[*]' COLUMNS (role_id VARCHAR(32) PATH '$')
                ) role_principal
                JOIN sys_user_role user_role
                  ON CAST(user_role.role_id AS CHAR) = role_principal.role_id
                 AND user_role.user_id = #{query.userId}
                 AND user_role.deleted_at = 0
                JOIN sys_role role
                  ON role.id = user_role.role_id
                 AND role.status = 1
                 AND role.deleted_at = 0
            )
        )
        OR (
            JSON_UNQUOTE(
                JSON_EXTRACT(
                    a.nodes_snapshot,
                    CONCAT('$[', a.current_node_index, '].approverType')
                )
            ) = 'DEPARTMENTS'
            AND EXISTS (
                SELECT 1
                FROM JSON_TABLE(
                    COALESCE(
                        JSON_EXTRACT(
                            a.nodes_snapshot,
                            CONCAT('$[', a.current_node_index, '].departmentIds')
                        ),
                        JSON_ARRAY()
                    ),
                    '$[*]' COLUMNS (department_id VARCHAR(32) PATH '$')
                ) department_principal
                JOIN sys_department pending_department
                  ON CAST(pending_department.id AS CHAR) = department_principal.department_id
                 AND pending_department.status = 1
                 AND pending_department.deleted_at = 0
                JOIN sys_user pending_department_user
                  ON pending_department_user.primary_department_id = pending_department.id
                 AND pending_department_user.id = #{query.userId}
                 AND pending_department_user.status = 1
                 AND pending_department_user.deleted_at = 0
            )
        )
    )
)

AND (
    
    OR (a.status = 'PROCESSING' AND a.approver_id = #{query.userId})
    OR EXISTS (
        SELECT 1
        FROM media_asset_approval_log visible_log
        WHERE visible_log.application_id = a.id
          AND visible_log.actor_id = #{query.userId}
          AND visible_log.action IN ('APPROVED', 'REJECTED')
    )
    OR FIND_IN_SET(
        CAST(#{query.userId} AS CHAR),
        REPLACE(
            COALESCE(JSON_UNQUOTE(JSON_EXTRACT(a.form_data, '$._ccUserIds')), ''),
            ' ',
            ''
        )
    ) > 0
    OR a.requester_id = #{query.userId}
)

sql.if:

AND (
    CAST(a.id AS CHAR) LIKE #{keywordPattern}
    OR a.application_no LIKE #{keywordPattern}
    OR a.title LIKE #{keywordPattern}
    OR a.requester_name LIKE #{keywordPattern}
    OR a.reason LIKE #{keywordPattern}
    OR JSON_UNQUOTE(JSON_EXTRACT(a.form_data, '$.projectName')) LIKE #{keywordPattern}
    OR JSON_UNQUOTE(JSON_EXTRACT(a.form_data, '$.channelName')) LIKE #{keywordPattern}
)

AND EXISTS (
    SELECT 1
    FROM media_asset_approval_log decision_log
    WHERE decision_log.application_id = a.id
      AND decision_log.actor_id = #{query.userId}
      AND decision_log.action = #{query.decisionResult}
)

mapper.select:
SELECT id, COALESCE( NULLIF(real_name, ''), NULLIF(display_name, ''), NULLIF(username, ''), CONCAT('用户 ', id) ) displayName, status FROM sys_user WHERE id IN
#{id}
AND deleted_at = 0

SELECT a.id, a.application_no applicationNo, COALESCE( ( SELECT definition.application_name FROM media_application_definition definition WHERE definition.id = CAST( JSON_UNQUOTE(JSON_EXTRACT(a.form_data, '$.applicationDefinitionId')) AS UNSIGNED ) AND definition.deleted_at = 0 LIMIT 1 ), NULLIF(JSON_UNQUOTE(JSON_EXTRACT(a.form_data, '$.applicationName')), ''), a.asset_type ) applicationTypeName, a.asset_type assetType, a.title, a.quantity, a.reason, a.status, a.requester_id requesterId, a.requester_name requesterName, a.approver_id approverId, a.approver_name approverName, a.form_data formData, a.nodes_snapshot nodes, a.created_at createdAt, a.updated_at updatedAt, departmentId, departmentName, COALESCE( NULLIF(JSON_UNQUOTE(JSON_EXTRACT(a.form_data, '$.projectName')), ''), NULLIF(JSON_UNQUOTE(JSON_EXTRACT(a.form_data, '$.channelName')), ''), NULLIF(JSON_UNQUOTE(JSON_EXTRACT(a.form_data, '$.project')), '') ) projectName
AND a.id IN
#{applicationId}

SELECT application_id applicationId, id, action, actor_id actorId, actor_name actorName, remark, action_data actionData, node_index nodeIndex, node_name nodeName, created_at createdAt FROM media_asset_approval_log WHERE application_id IN
#{applicationId}
ORDER BY application_id, id

SELECT application_id applicationId, id, asset_type assetType, asset_name assetName, asset_code assetCode, channel_name channelName, project_name projectName FROM media_asset WHERE application_id IN
#{applicationId}
AND deleted_at = 0 ORDER BY application_id, id

SELECT DISTINCT asset.account_id FROM ad_account_asset asset JOIN ad_account_asset_assignment assignment ON assignment.ad_account_asset_id = asset.id AND assignment.user_id = #{assigneeId} AND assignment.assignment_status = 'ACTIVE' AND assignment.deleted_at = 0 WHERE asset.account_id IN
#{accountId}
AND asset.deleted_at = 0

mapper.insert:
INSERT INTO ad_account_asset_assignment ( ad_account_asset_id, user_id, user_name, is_primary, assignment_status, assignment_source, application_id, assigned_at, created_by, updated_by ) SELECT asset.id, #{assigneeId}, #{assigneeName}, 1, 'ACTIVE', 'APPLICATION', #{applicationId}, CURRENT_TIMESTAMP(3), #{operatorId}, #{operatorId} FROM ad_account_asset asset WHERE asset.account_id IN
#{accountId}
AND asset.deleted_at = 0 AND asset.id = ( SELECT MAX(candidate.id) FROM ad_account_asset candidate WHERE candidate.account_id = asset.account_id AND candidate.deleted_at = 0 ) ON DUPLICATE KEY UPDATE user_name = VALUES(user_name), is_primary = 1, assignment_status = 'ACTIVE', assignment_source = 'APPLICATION', application_id = VALUES(application_id), released_at = NULL, updated_by = VALUES(updated_by), updated_at = CURRENT_TIMESTAMP(3)
